def find_permutation(n):
    if n == 1:
        return "YES\n1"
    if n == 2 or n == 3:
        return "NO"

    # For n >= 4, we can construct a valid permutation
    permutation = [0] * n
    for i in range(n):
        if i % 2 == 0:
            permutation[i] = (i // 2) + 1
        else:
            permutation[i] = n - (i // 2)

    # Check if the prefix product sequence is a permutation of [0, 1, ..., n - 1]
    prefix_product = [0] * n
    current_product = 1
    for i in range(n):
        current_product *= permutation[i]
        prefix_product[i] = current_product - 1

    if sorted(prefix_product) == list(range(n)):
        result = "YES\n" + "\n".join(map(str, permutation))
        return result
    else:
        return "NO"

